mapper.select:
SELECT i.inquiry_id, i.branch_code, i.title, i.content, i.category, i.urgency, i.status, DATE_FORMAT(i.created_at, '%Y-%m-%d %H:%i:%s') AS created_at_formatted, b.name AS branch_name, r.reply_id, r.author_id, a.emp_no, e.name AS author_name, rb.name AS reply_author_affiliation, r.content AS reply_content, DATE_FORMAT(r.created_at, '%Y-%m-%d %H:%i:%s') AS reply_created_at_formatted FROM inquiry i JOIN branch b ON i.branch_code = b.branch_code LEFT JOIN inquiry_reply r ON i.inquiry_id = r.inquiry_id LEFT JOIN account a ON r.author_id = a.account_id LEFT JOIN employee e ON a.emp_no = e.emp_no LEFT JOIN branch rb ON a.branch_code = rb.branch_code
i.branch_code = #{branchCode}
AND i.category = #{category}
AND i.status = #{status}
ORDER BY i.created_at DESC, r.created_at ASC

mapper.update:
UPDATE inquiry
SET title = #{title}, content = #{content}, category = #{category}, urgency = #{urgency}
WHERE inquiry_id = #{inquiryId}
